<!doctype html><html><head><meta charset="utf-8"><title>{{ __('Invoice') }} {{ $invoice->invoice_number }}</title><style>body{font-family:Arial;margin:40px;color:#222}.head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:18px}table{width:100%;border-collapse:collapse;margin-top:28px}td,th{border:1px solid #ccc;padding:12px}.right{text-align:right}@media print{button{display:none}}</style></head><body><button onclick="window.print()">{{ __('Print') }}</button><div class="head"><div><h1>{{ __('Commercial Invoice') }}</h1><p>{{ $invoice->invoice_number }}</p></div><div>{{ $invoice->issue_date?->format('d M Y') }}</div></div><p><strong>{{ __('Buyer') }}:</strong> {{ $invoice->order?->buyer?->company_name }}</p><p><strong>{{ __('Order') }}:</strong> {{ $invoice->order?->order_number }}</p><table><tr><th>{{ __('Description') }}</th><th class="right">{{ __('Amount') }}</th></tr><tr><td>{{ $invoice->order?->product_description ?: __('Garment order') }}</td><td class="right">{{ $invoice->currency }} {{ number_format((float) $invoice->amount, 2) }}</td></tr><tr><td class="right">{{ __('Tax') }}</td><td class="right">{{ $invoice->currency }} {{ number_format((float) $invoice->tax_amount, 2) }}</td></tr><tr><th class="right">{{ __('Total') }}</th><th class="right">{{ $invoice->currency }} {{ number_format((float) $invoice->total_amount, 2) }}</th></tr></table><p>{{ $invoice->notes }}</p></body></html>
